public without sharing class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    private Integer recordsUpdated;
    private Integer recordsFailed;
    private Decimal overdueAmount;

    public OverdueInvoiceBatch() {
        this.recordsUpdated = 0;
        this.recordsFailed = 0;
        this.overdueAmount = 0;
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
            AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        processScope(scope);
    }

    // Overload so execute can also be called directly with a typed invoice list.
    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> scope) {
        if (scope == null) {
            return;
        }
        List<SObject> records = new List<SObject>();
        for (FB_Invoice__c invoice : scope) {
            records.add(invoice);
        }
        processScope(records);
    }

    private void processScope(List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        if (this.recordsUpdated == null) {
            this.recordsUpdated = 0;
        }
        if (this.recordsFailed == null) {
            this.recordsFailed = 0;
        }
        if (this.overdueAmount == null) {
            this.overdueAmount = 0;
        }

        List<FB_Invoice__c> invoices = new List<FB_Invoice__c>();
        for (SObject record : scope) {
            FB_Invoice__c invoice = (FB_Invoice__c) record;
            invoice.Status__c = 'Overdue';
            invoices.add(invoice);
        }

        List<Database.SaveResult> results = Database.update(invoices, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                this.recordsUpdated++;
                this.overdueAmount += (invoices[i].Amount__c == null ? 0 : invoices[i].Amount__c);
            } else {
                this.recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = (this.recordsUpdated == null ? 0 : this.recordsUpdated),
            Records_Failed__c = (this.recordsFailed == null ? 0 : this.recordsFailed),
            Overdue_Amount__c = (this.overdueAmount == null ? 0 : this.overdueAmount)
        );
        insert summary;
    }
}
