public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(
            required=true
            label='Email'
            description='Email address to look up'
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact, if found'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True if a matching Contact was found'
        )
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact by email address. Matching is case-insensitive. If multiple Contacts match, the earliest created Contact is returned.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        Set<String> distinctEmailSet = new Set<String>();
        List<String> distinctEmails = new List<String>();

        for (Request request : requests) {
            String normalizedEmail = normalizeEmail(
                request == null ? null : request.email
            );
            normalizedEmails.add(normalizedEmail);

            if (normalizedEmail != null && distinctEmailSet.add(normalizedEmail)) {
                distinctEmails.add(normalizedEmail);
            }
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();

        if (!distinctEmails.isEmpty()) {
            // Use a single dynamic query with LIKE for every distinct email.
            // LIKE matching in SOQL is case-insensitive, whereas IN/= with a
            // lower-cased bind variable is case-sensitive and would miss
            // Contacts stored with different capitalisation.
            // Wildcards in the email are escaped so LIKE acts as an exact
            // match, and String.escapeSingleQuotes prevents SOQL injection.
            List<String> conditions = new List<String>();

            for (String normalizedEmail : distinctEmails) {
                conditions.add(
                    'Email LIKE \'' + toLikeLiteralPattern(normalizedEmail) + '\''
                );
            }

            String soql =
                'SELECT Id, Email FROM Contact WHERE ' +
                String.join(conditions, ' OR ') +
                ' ORDER BY CreatedDate ASC, Id ASC';

            for (Contact contactRecord : (List<Contact>) Database.query(soql)) {
                String contactEmail = normalizeEmail(contactRecord.Email);

                if (
                    contactEmail != null &&
                    distinctEmailSet.contains(contactEmail) &&
                    !contactIdByEmail.containsKey(contactEmail)
                ) {
                    contactIdByEmail.put(contactEmail, contactRecord.Id);
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalizedEmail = normalizedEmails[i];
            Id matchedContactId = normalizedEmail == null
                ? null
                : contactIdByEmail.get(normalizedEmail);

            Result result = new Result();
            result.contactId = matchedContactId;
            result.found = matchedContactId != null;
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    private static String toLikeLiteralPattern(String value) {
        // Escape LIKE wildcards so the pattern is an exact match, not a
        // substring/wildcard match. Backslash must be escaped first.
        String pattern = value
            .replace('\\', '\\\\')
            .replace('%', '\\%')
            .replace('_', '\\_');

        // Escape single quotes for safe use as a SOQL string literal.
        return String.escapeSingleQuotes(pattern);
    }
}
