@IsTest
private class AddressVerificationServiceTest {

    // ---------------------------------------------------------------------
    // Test setup: persisted data is created in a separate transaction, so
    // tests querying it can make callouts without the
    // "uncommitted work pending" error caused by DML in the same
    // transaction as the callout.
    // ---------------------------------------------------------------------

    @TestSetup
    static void makePersistedAccount() {
        insert new Account(
            Name = 'Persisted Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Metropolis',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
        );
    }

    // ---------------------------------------------------------------------
    // Mock
    // ---------------------------------------------------------------------

    private class CapturingMock implements HttpCalloutMock {
        private final Integer statusCode;
        private final String responseBody;

        public Integer callCount = 0;
        public String lastMethod;
        public String lastEndpoint;
        public String lastContentType;
        public String lastBody;

        CapturingMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            lastMethod = req.getMethod();
            lastEndpoint = req.getEndpoint();
            lastContentType = req.getHeader('Content-Type');
            lastBody = req.getBody();

            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            if (responseBody != null) {
                res.setBody(responseBody);
            }
            return res;
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Account newAccount(
        String street,
        String city,
        String postalCode,
        String country
    ) {
        return new Account(
            Name = 'Acme Test',
            BillingStreet = street,
            BillingCity = city,
            BillingPostalCode = postalCode,
            BillingCountry = country
        );
    }

    private static CapturingMock installMock(Integer statusCode, String responseBody) {
        CapturingMock mock = new CapturingMock(statusCode, responseBody);
        Test.setMock(HttpCalloutMock.class, mock);
        return mock;
    }

    /**
     * Case-sensitive string comparison, so mutations that change only the
     * casing of a status, endpoint, header, key value or field value fail.
     */
    private static void assertExactString(String expected, String actual, String message) {
        Assert.isTrue(
            expected != null && expected.equals(actual),
            message + ' Expected: [' + expected + '] Actual: [' + actual + ']'
        );
    }

    private static void assertBilling(
        Account acct,
        String street,
        String city,
        String postalCode,
        String country
    ) {
        if (street == null) {
            Assert.isNull(acct.BillingStreet, 'BillingStreet should be null');
        } else {
            assertExactString(street, acct.BillingStreet, 'BillingStreet mismatch.');
        }
        if (city == null) {
            Assert.isNull(acct.BillingCity, 'BillingCity should be null');
        } else {
            assertExactString(city, acct.BillingCity, 'BillingCity mismatch.');
        }
        if (postalCode == null) {
            Assert.isNull(acct.BillingPostalCode, 'BillingPostalCode should be null');
        } else {
            assertExactString(postalCode, acct.BillingPostalCode, 'BillingPostalCode mismatch.');
        }
        if (country == null) {
            Assert.isNull(acct.BillingCountry, 'BillingCountry should be null');
        } else {
            assertExactString(country, acct.BillingCountry, 'BillingCountry mismatch.');
        }
    }

    private static void assertRequestContract(
        CapturingMock mock,
        String street,
        String city,
        String postalCode,
        String country
    ) {
        Assert.areEqual(1, mock.callCount, 'Exactly one callout should be made');
        assertExactString('POST', mock.lastMethod, 'HTTP method mismatch.');
        assertExactString(
            'callout:FB_Address_API/v2/verify',
            mock.lastEndpoint,
            'Endpoint mismatch.'
        );
        assertExactString(
            'application/json',
            mock.lastContentType,
            'Content-Type header mismatch.'
        );
        Assert.isNotNull(mock.lastBody, 'Request body should not be null');

        Map<String, Object> body =
            (Map<String, Object>) JSON.deserializeUntyped(mock.lastBody);

        Assert.areEqual(4, body.size(), 'Request body should contain exactly four keys: ' + mock.lastBody);
        Assert.isTrue(body.containsKey('street'), 'Body should contain key "street": ' + mock.lastBody);
        Assert.isTrue(body.containsKey('city'), 'Body should contain key "city": ' + mock.lastBody);
        Assert.isTrue(body.containsKey('postalCode'), 'Body should contain key "postalCode": ' + mock.lastBody);
        Assert.isTrue(body.containsKey('country'), 'Body should contain key "country": ' + mock.lastBody);

        if (street == null) {
            Assert.isNull(body.get('street'), 'Body "street" should be null');
        } else {
            assertExactString(street, (String) body.get('street'), 'Body "street" mismatch.');
        }
        if (city == null) {
            Assert.isNull(body.get('city'), 'Body "city" should be null');
        } else {
            assertExactString(city, (String) body.get('city'), 'Body "city" mismatch.');
        }
        if (postalCode == null) {
            Assert.isNull(body.get('postalCode'), 'Body "postalCode" should be null');
        } else {
            assertExactString(postalCode, (String) body.get('postalCode'), 'Body "postalCode" mismatch.');
        }
        if (country == null) {
            Assert.isNull(body.get('country'), 'Body "country" should be null');
        } else {
            assertExactString(country, (String) body.get('country'), 'Body "country" mismatch.');
        }
    }

    private static void assertThrowsForStatus(Account acct, Integer statusCode) {
        CapturingMock mock = installMock(statusCode, '{"status":"ERROR"}');
        try {
            AddressVerificationService.verify(acct);
            Assert.fail('Expected AddressVerificationException for HTTP ' + statusCode);
        } catch (AddressVerificationService.AddressVerificationException e) {
            Assert.isNotNull(e.getMessage(), 'Exception message should not be null');
            Assert.isTrue(
                e.getMessage().contains(String.valueOf(statusCode)),
                'Exception message should contain status code ' + statusCode +
                    ' but was: ' + e.getMessage()
            );
        }
        Assert.areEqual(1, mock.callCount, 'Exactly one callout should be made before failing');
    }

    private static final String CORRECTED_BODY =
        '{"status":"CORRECTED","address":{' +
        '"street":"999 Corrected Avenue","city":"Springfield",' +
        '"postalCode":"99999-1234","country":"Correctedland"}}';

    private static final String DIFFERENT_ADDRESS_BODY_VERIFIED =
        '{"status":"VERIFIED","address":{' +
        '"street":"111 Should Not Apply Street","city":"ShouldNotApplyCity",' +
        '"postalCode":"11111","country":"ShouldNotApplyCountry"}}';

    private static final String DIFFERENT_ADDRESS_BODY_INVALID =
        '{"status":"INVALID","address":{' +
        '"street":"222 Should Not Apply Street","city":"ShouldNotApplyCity2",' +
        '"postalCode":"22222","country":"ShouldNotApplyCountry2"}}';

    // ---------------------------------------------------------------------
    // SKIPPED behaviour
    // ---------------------------------------------------------------------

    @IsTest
    static void skippedWhenBillingStreetIsNull() {
        Account acct = newAccount(null, 'Metropolis', '12345', 'USA');
        CapturingMock mock = installMock(200, DIFFERENT_ADDRESS_BODY_VERIFIED);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('SKIPPED', result.status, 'Result status mismatch.');
        Assert.areEqual(false, result.changed, 'changed should be false when skipped');
        Assert.areEqual(0, mock.callCount, 'No callout should be made when BillingStreet is blank');
        assertBilling(acct, null, 'Metropolis', '12345', 'USA');
    }

    @IsTest
    static void skippedWhenBillingStreetIsEmpty() {
        Account acct = newAccount('', 'Metropolis', '12345', 'USA');
        CapturingMock mock = installMock(200, DIFFERENT_ADDRESS_BODY_VERIFIED);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('SKIPPED', result.status, 'Result status mismatch.');
        Assert.areEqual(false, result.changed, 'changed should be false when skipped');
        Assert.areEqual(0, mock.callCount, 'No callout should be made when BillingStreet is empty');
        assertBilling(acct, '', 'Metropolis', '12345', 'USA');
    }

    @IsTest
    static void skippedWhenBillingStreetIsWhitespace() {
        Account acct = newAccount('   ', 'Metropolis', '12345', 'USA');
        CapturingMock mock = installMock(200, DIFFERENT_ADDRESS_BODY_VERIFIED);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('SKIPPED', result.status, 'Result status mismatch.');
        Assert.areEqual(false, result.changed, 'changed should be false when skipped');
        Assert.areEqual(0, mock.callCount, 'No callout should be made when BillingStreet is whitespace');
        assertBilling(acct, '   ', 'Metropolis', '12345', 'USA');
    }

    @IsTest
    static void notSkippedWhenStreetPresentButOtherFieldsBlank() {
        Account acct = newAccount('123 Main St', null, null, null);
        CapturingMock mock = installMock(200, '{"status":"VERIFIED","address":{}}');

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('VERIFIED', result.status, 'Result status mismatch.');
        Assert.areEqual(false, result.changed, 'changed should be false for VERIFIED');
        Assert.areEqual(1, mock.callCount, 'A callout should be made when BillingStreet is present');
    }

    // ---------------------------------------------------------------------
    // Request contract
    // ---------------------------------------------------------------------

    @IsTest
    static void sendsCorrectRequestContract() {
        Account acct = newAccount('123 Main St', 'Metropolis', '12345', 'USA');
        CapturingMock mock = installMock(200, DIFFERENT_ADDRESS_BODY_VERIFIED);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('VERIFIED', result.status, 'Result status mismatch.');
        assertRequestContract(mock, '123 Main St', 'Metropolis', '12345', 'USA');
    }

    @IsTest
    static void sendsEachBillingFieldToItsOwnJsonKey() {
        // Distinct value per field so any field/key swap is detected.
        Account acct = newAccount(
            'STREET-VALUE-1',
            'CITY-VALUE-2',
            'POSTAL-VALUE-3',
            'COUNTRY-VALUE-4'
        );
        CapturingMock mock = installMock(200, '{"status":"INVALID","address":{}}');

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('INVALID', result.status, 'Result status mismatch.');
        assertRequestContract(
            mock,
            'STREET-VALUE-1',
            'CITY-VALUE-2',
            'POSTAL-VALUE-3',
            'COUNTRY-VALUE-4'
        );
    }

    @IsTest
    static void sendsNullOptionalFieldsAsJsonNullKeys() {
        Account acct = newAccount('456 Only Street', null, null, null);
        CapturingMock mock = installMock(200, '{"status":"VERIFIED","address":{}}');

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('VERIFIED', result.status, 'Result status mismatch.');
        assertRequestContract(mock, '456 Only Street', null, null, null);
    }

    @IsTest
    static void sendsRequestContractForCorrectedResponse() {
        Account acct = newAccount('789 Contract Road', 'Gotham', '54321', 'Canada');
        CapturingMock mock = installMock(200, CORRECTED_BODY);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('CORRECTED', result.status, 'Result status mismatch.');
        assertRequestContract(mock, '789 Contract Road', 'Gotham', '54321', 'Canada');
    }

    // ---------------------------------------------------------------------
    // VERIFIED
    // ---------------------------------------------------------------------

    @IsTest
    static void verifiedLeavesAccountUntouchedAndChangedFalse() {
        Account acct = newAccount('123 Main St', 'Metropolis', '12345', 'USA');
        CapturingMock mock = installMock(200, DIFFERENT_ADDRESS_BODY_VERIFIED);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        assertExactString('VERIFIED', result.status, 'Result status mismatch.');
        Assert.areEqual(false, result.changed, 'changed should be false for VERIFIED');
        Assert.areEqual(1, mock.callCount, 'Exactly one callout should be made');
        // Even though the response carries a different address, it must not be applied.
        assertBilling(acct, '123 Main St', 'Metropolis', '12345', 'USA');
    }

    @IsTest
    static void verifiedWithNoAddressLeavesAccountUntouched() {
        Account acct = newAccount('123 Main St', 'Metropolis', '12345', 'USA');
        installMock(200, '{"status":"VERIFIED"}');

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

