            InvoicingService.invoiceWonOpportunities(opportunityIds);
            Assert.fail('Expected InvoicingService.InvoicingException to be thrown');
        } catch (InvoicingService.InvoicingException e) {
            Assert.isTrue(
                e.getMessage().contains('Authentication token expired'),
                'InvoicingException message should contain the gateway message, was: ' + e.getMessage()
            );
        }
