        IOpportunitiesSelector selectorMock = stubSelector(mocks, accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'Result map should not be null.');
        Assert.areEqual(2, result.size(), 'Result should contain exactly the two returned stages.');
        Assert.areEqual(
            132.00,
            result.get('Prospecting'),
            'Prospecting should sum the per-opportunity rounded weighted amounts.'
        );
        Assert.areEqual(
