```apex
/**
 * Closes stale, still-open Opportunities as 'Closed Lost'.
 *
 * WHAT I CHANGED RELATIVE TO THE REQUESTED DESIGN, AND WHY
 * ---------------------------------------------------------
 * 1) The requested synchronous entry point, closeStale(Date), is kept for
 *    compatibility and for small/ad-hoc runs, and it does use the requested
 *    list-form SOQL for loop. That loop only solves memory/heap usage: the
 *    query is fetched in chunks (200 records) instead of materialising every
 *    row at once.
 *
 *    It does NOT solve transaction governor limits. A synchronous call is
 *    still ONE transaction that accumulates every DML row, DML statement and
 *    all CPU spent in Opportunity triggers/Flows/validations. It therefore
 *    cannot exceed 10,000 DML rows (i.e. 50 chunks of 200), 150 DML
 *    statements or 50,000 queried rows, however the rows are chunked. A few
 *    thousand records fits today, but a single larger night fails and, if
 *    the failure is unhandled, rolls back the whole job - so nothing is
 *    closed and the backlog is even bigger the next night.
 *
 * 2) The preferred production path is therefore Batch Apex, exposed via
 *    closeStaleAsync(Date) below. The Schedulable should call
 *    Database.executeBatch(...) instead of calling closeStale(...) and
 *    reading a return value. Each batch of 200 gets fresh governor limits,
 *    so the job scales to any backlog, and one bad batch does not undo
 *    batches that already committed. The unavoidable trade-off is that a
 *    batch job cannot return the count synchronously to the Schedulable:
 *    the count is accumulated in closedCount/failedCount
 *    (Database.Stateful) and reported from finish() instead - wire that
 *    hook to the org's real reporting (log record / email / platform
 *    event) rather than relying on the debug statement left there.
 *
 *    NOTE ON THE BATCHABLE GENERIC: this class implements
 *    Database.Batchable<sObject>, not Database.Batchable<Opportunity>.
 *    A start() method returning Database.QueryLocator is only valid when
 *    the type parameter is sObject; with a concrete type such as
 *    Opportunity the compiler requires start() to return
 *    Iterable<Opportunity> instead, and the class fails to compile.
 *
 * 3) Updates use Database.update(chunk, false, ...) and only successful
 *    SaveResults are counted. With a plain `update chunk;` (allOrNone),
 *    one record failing a validation rule, a lock or a Closed-Lost
 *    required-field rule would throw and roll back every chunk already
 *    processed in the same transaction. Here failures are logged with
 *    their record Id and the job carries on with the remaining records;
 *    consequently the returned/accumulated count is the number actually
 *    closed, not the number attempted.
 *
 * SECURITY / SHARING
 * ------------------
 * This is intentionally `without sharing` and uses SYSTEM_MODE: it is a
 * system automation whose contract is to close EVERY stale open
 * Opportunity, not only those visible to whichever user happened to
 * schedule it. Compensating control: grant Apex class access only to the
 * admin/integration profiles that own the schedule. If org policy instead
 * requires user-mode enforcement, switch SYSTEM_MODE to USER_MODE - the
 * job will then only close records the scheduling user may access, and
 * the counts will (correctly) reflect that smaller set.
 */
public without sharing class StaleOpportunityCloser
    implements Database.Batchable<sObject>, Database.Stateful {

    private static final String CLOSED_LOST = 'Closed Lost';
    private static final Integer BATCH_SIZE = 200;

    /** Cut-off for the batch instance; null means "today" (see start()). */
    private Date cutoff;

    /** Stateful counters, preserved across batch chunks and read in finish(). */
    private Integer closedCount = 0;
    private Integer failedCount = 0;

    private class InvalidCutoffException extends Exception {}

    /** No-arg constructor required so the class can be scheduled/instantiated reflectively. */
    public StaleOpportunityCloser() {
        this.cutoff = null;
    }

    public StaleOpportunityCloser(Date cutoff) {
        this.cutoff = cutoff;
    }

    // ------------------------------------------------------------------
    // Synchronous API (requested). Suitable only while the stale backlog
    // comfortably fits inside a single transaction's limits; prefer
    // closeStaleAsync for the nightly production job.
    // ------------------------------------------------------------------

    /**
     * Closes every open Opportunity with CloseDate strictly before cutoff
     * (an Opportunity closing exactly on cutoff stays open) and returns how
     * many were actually closed.
     */
    public static Integer closeStale(Date cutoff) {
        requireCutoff(cutoff);

        Integer closed = 0;
        // List-form SOQL for loop: Salesforce fetches the query in chunks of
        // 200, so the full result set is never held in memory at once. The
        // QueryLocator snapshot is taken up front, so updating records to
        // Closed Lost while iterating does not disturb the iteration.
        for (List<Opportunity> chunk : [
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
            AND CloseDate < :cutoff
            WITH SYSTEM_MODE
        ]) {
            closed += closeChunk(chunk);
        }
        return closed;
    }

    /**
     * Preferred production entry point. Launches this class as a batch job
     * and returns the AsyncApexJob Id; the closed/failed counts are reported
     * from finish(), because no synchronous return value is possible.
     */
    public static Id closeStaleAsync(Date cutoff) {
        requireCutoff(cutoff);
        return Database.executeBatch(new StaleOpportunityCloser(cutoff), BATCH_SIZE);
    }

    // ------------------------------------------------------------------
    // Database.Batchable implementation
    // Type parameter is sObject, as required for a QueryLocator start().
    // ------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext context) {
        // Evaluated when the batch starts, not when the job was scheduled,
        // so a recurring schedule always uses the current date.
        Date effectiveCutoff = (cutoff == null) ? Date.today() : cutoff;
        return Database.getQueryLocator([
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
            AND CloseDate < :effectiveCutoff
            WITH SYSTEM_MODE
        ]);
    }

    public void execute(Database.BatchableContext context, List<sObject> scope) {
        List<Opportunity> chunk = new List<Opportunity>();
        for (sObject record : scope) {
            chunk.add((Opportunity) record);
        }
        Integer succeeded = closeChunk(chunk);
        closedCount += succeeded;
        failedCount += (chunk.size() - succeeded);
    }

    public void finish(Database.BatchableContext context) {
        // Reporting hook: the Schedulable cannot receive this count as a
        // return value from an asynchronous job, so report it here through
        // the org's normal channel (persistent log, email, event, ...).
        System.debug(
            LoggingLevel.INFO,
            'StaleOpportunityCloser finished for cutoff ' +
            String.valueOf(cutoff == null ? Date.today() : cutoff) +
            ': closed=' + closedCount + ', failed=' + failedCount
        );
    }

    // ------------------------------------------------------------------
    // Shared helpers
    // ------------------------------------------------------------------

    /**
     * Marks one chunk as Closed Lost and updates it with partial success
     * enabled. Returns the number of records actually updated; each failure
     * is logged (record Id + errors) so it can be investigated and retried
     * on the next run, where the still-open record will be picked up again.
     */
    private static Integer closeChunk(List<Opportunity> chunk) {
        if (chunk == null || chunk.isEmpty()) {
            return 0;
        }
        for (Opportunity opp : chunk) {
            opp.StageName = CLOSED_LOST;
        }

        Integer succeeded = 0;
        List<Database.SaveResult> results =
            Database.update(chunk, false, AccessLevel.SYSTEM_MODE);
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (result.isSuccess()) {
                succeeded++;
            } else {
                for (Database.Error err : result.getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'StaleOpportunityCloser: failed to close Opportunity ' +
                        chunk[i].Id + ' [' + err.getStatusCode() + '] ' +
                        err.getMessage() +
                        ' fields=' + String.join(err.getFields(), ',')
                    );
                }
            }
        }
        return succeeded;
    }

    private static void requireCutoff(Date cutoff) {
        if (cutoff == null) {
            // Fail loudly: silently treating null as "close nothing" would
            // let a misconfigured schedule look successful every night.
            throw new InvalidCutoffException('cutoff must not be null.');
        }
    }
}
