import { LightningElement, api } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = -1;
    _optionIdPrefix;

    constructor() {
        super();
        instanceCount += 1;
        this._optionIdPrefix = `status-listbox-option-${instanceCount}`;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncActiveToValue();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._syncActiveToValue();
    }

    _syncActiveToValue() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex === -1 ? 0 : selectedIndex;
    }

    get activeId() {
        if (
            this._activeIndex < 0 ||
            !this._options ||
            this._activeIndex >= this._options.length
        ) {
            return undefined;
        }
        return `${this._optionIdPrefix}-${this._activeIndex}`;
    }

    get renderedOptions() {
        return (this._options || []).map((option, index) => ({
            label: option.label,
            value: option.value,
            index,
            id: `${this._optionIdPrefix}-${index}`,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeyDown(event) {
        const count = this._options ? this._options.length : 0;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex =
                        this._activeIndex < 0
                            ? 0
                            : Math.min(this._activeIndex + 1, count - 1);
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex =
                        this._activeIndex < 0
                            ? 0
                            : Math.max(this._activeIndex - 1, 0);
                }
                break;
            case 'Home':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex = count - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActive();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = this._resolveClickedIndex(event);
        if (index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        this._selectValue(this._options[index].value);
    }

    _resolveClickedIndex(event) {
        const options = this._options || [];

        // Resolve from the actual clicked DOM node first. This is the
        // most reliable source inside the component's own shadow tree
        // (event.target is the <li>; dataset/currentTarget handling can
        // differ between the real browser and test environments).
        const nodes = [
            event.target,
            event.currentTarget,
            event.target &&
            typeof event.target.closest === 'function'
                ? event.target.closest('li')
                : null
        ];

        for (const node of nodes) {
            if (!node) {
                continue;
            }
            // Position of the clicked node among the rendered options.
            try {
                const items = this.template.querySelectorAll(
                    '[role="option"]'
                );
                const position = Array.prototype.indexOf.call(items, node);
                if (position !== -1) {
                    return position;
                }
            } catch (e) {
                // Fall through to attribute-based resolution.
            }
            // Value carried by the clicked node.
            let nodeValue;
            if (typeof node.getAttribute === 'function') {
                nodeValue = node.getAttribute('data-value');
            }
            if (nodeValue === null || nodeValue === undefined) {
                nodeValue = node.dataset ? node.dataset.value : undefined;
            }
            if (nodeValue !== null && nodeValue !== undefined) {
                const byValue = options.findIndex(
                    (option) => option.value === nodeValue
                );
                if (byValue !== -1) {
                    return byValue;
                }
            }
            // Index carried by the clicked node.
            let nodeIndex;
            if (typeof node.getAttribute === 'function') {
                nodeIndex = node.getAttribute('data-index');
            }
            if (nodeIndex === null || nodeIndex === undefined) {
                nodeIndex = node.dataset ? node.dataset.index : undefined;
            }
            if (nodeIndex !== null && nodeIndex !== undefined) {
                const parsed = Number(nodeIndex);
                if (Number.isInteger(parsed)) {
                    return parsed;
                }
            }
        }

        return -1;
    }

    _selectActive() {
        if (
            this._activeIndex < 0 ||
            !this._options ||
            this._activeIndex >= this._options.length
        ) {
            return;
        }
        this._selectValue(this._options[this._activeIndex].value);
    }

    _selectValue(value) {
        if (value === this._value) {
            return;
        }
        // Track the selection internally so that aria-selected reflects
        // it immediately and re-selecting the same option (before or
        // after the parent updates `value`) dispatches nothing. A later
        // assignment to the `value` API property overwrites this.
        this._value = value;
        const selectedIndex = (this._options || []).findIndex(
            (option) => option.value === value
        );
        if (selectedIndex !== -1) {
            this._activeIndex = selectedIndex;
        }
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
