/**
 * Imports one-off web gifts through the NPSP Data Importer (BDI).
 *
 * Staging one npsp__DataImport__c per gift preserves that record as the
 * audit trail of the import, and processing through NPSP's Apex API
 * applies NPSP's own contact matching, household creation and donation
 * processing rules instead of creating duplicate donors directly.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stages and synchronously processes one NPSP Data Import record per
     * gift, in this transaction. Returns one result per gift, in input order.
     * A row rejected by NPSP is reported as a failed result and does not
     * prevent the remaining rows from being processed.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one Data Import record per gift (bulk DML, never in a loop).
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            dataImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift == null ? null : gift.firstName,
                npsp__Contact1_Lastname__c       = gift == null ? null : gift.lastName,
                npsp__Contact1_Personal_Email__c = gift == null ? null : gift.email,
                npsp__Donation_Donor__c          = 'Contact1',
                npsp__Donation_Amount__c         = gift == null ? null : gift.amount,
                npsp__Donation_Date__c           = gift == null ? null : gift.giftDate
            ));
        }
        insert dataImports;

        // Use the org's Data Import settings. getInstance() returns the
        // applicable hierarchy settings; where no value is configured,
        // NPSP applies its defaults (contact matching on first name, last
        // name and email, and no matching of existing donations).
        npsp__Data_Import_Settings__c dataImportSettings =
            npsp__Data_Import_Settings__c.getInstance();
        if (dataImportSettings == null) {
            dataImportSettings = new npsp__Data_Import_Settings__c();
        }

        // Process all staged records synchronously, in this transaction,
        // through NPSP's Data Import API (an instance API, not a static
        // one). NPSP marks each record Imported or Failed and records
        // per-row failures on the record itself; it does not abort the
        // whole set for an individual bad row. A call-level exception is
        // captured so results can still be built from the staged records.
        String processingError;
        try {
            npsp.BDI_DataImport_API dataImportApi = new npsp.BDI_DataImport_API();
            dataImportApi.processDataImportRecords(
                dataImports, dataImportSettings, false
            );
        } catch (Exception e) {
            processingError = e.getMessage();
        }

        // Re-query the processed records for NPSP's persisted outcomes.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImports
        ]);

        // Build one result per gift, preserving input order.
        for (npsp__DataImport__c staged : dataImports) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c processed = processedById.get(staged.Id);

            if (processed == null) {
                result.success = false;
                result.errorMessage = processingError;
            } else {
                result.success = 'Imported'.equalsIgnoreCase(processed.npsp__Status__c);
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                if (result.success) {
                    result.errorMessage = null;
                } else if (String.isNotBlank(processed.npsp__FailureInformation__c)) {
                    result.errorMessage = processed.npsp__FailureInformation__c;
                } else {
                    result.errorMessage = processingError;
                }
            }
            results.add(result);
        }
        return results;
    }
}
