public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist: null');
        }

        Date effectiveGiftDate = (giftDate == null) ? Date.today() : giftDate;

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donors[0];

        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact has no household account: ' + contactId
            );
        }

        // Every Contact on the same (household) Account gets a Contact Role.
        List<Contact> householdContacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
            WITH USER_MODE
            ORDER BY LastName ASC, FirstName ASC, Id ASC
        ];
        Set<Id> householdContactIds = new Set<Id>();
        for (Contact householdContact : householdContacts) {
            householdContactIds.add(householdContact.Id);
        }
        // Defensive: the donor was readable above, so always include them.
        householdContactIds.add(donor.Id);

        Opportunity gift = new Opportunity(
            Name = buildOpportunityName(donor, effectiveGiftDate),
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = effectiveGiftDate,
            StageName = 'Closed Won'
        );
        Id donationRecordTypeId = getDonationRecordTypeId();
        if (donationRecordTypeId != null) {
            gift.RecordTypeId = donationRecordTypeId;
        }

        insert as user gift;

        // NPSP TDTM automation runs synchronously during the Opportunity
        // insert and, with Payments / Contact Role creation enabled, may
        // already have created a Payment and Contact Roles for the primary
        // contact (and household). Reconcile whatever exists instead of
        // blindly inserting, so we never duplicate a role or a payment.
        reconcileContactRoles(gift.Id, donor.Id, householdContactIds);
        reconcilePayment(gift.Id, amount, effectiveGiftDate);

        return gift.Id;
    }

    private static void reconcileContactRoles(
        Id opportunityId,
        Id donorId,
        Set<Id> householdContactIds
    ) {
        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ];

        Map<Id, OpportunityContactRole> keeperByContactId =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole role : existing) {
            if (
                !householdContactIds.contains(role.ContactId) ||
                keeperByContactId.containsKey(role.ContactId)
            ) {
                // Not a household member, or a duplicate role for a
                // contact that already has one: remove it.
                toDelete.add(role);
            } else {
                keeperByContactId.put(role.ContactId, role);
            }
        }
        if (!toDelete.isEmpty()) {
            delete as user toDelete;
        }

        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();

        for (Id householdContactId : householdContactIds) {
            Boolean isDonor = (householdContactId == donorId);
            String desiredRole = isDonor ? 'Donor' : 'Household Member';

            OpportunityContactRole keeper = keeperByContactId.get(householdContactId);
            if (keeper == null) {
                toInsert.add(
                    new OpportunityContactRole(
                        OpportunityId = opportunityId,
                        ContactId = householdContactId,
                        Role = desiredRole,
                        IsPrimary = isDonor
                    )
                );
            } else if (keeper.Role != desiredRole || keeper.IsPrimary != isDonor) {
                keeper.Role = desiredRole;
                keeper.IsPrimary = isDonor;
                toUpdate.add(keeper);
            }
        }

        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
    }

    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existing = [
            SELECT
                Id,
                npe01__Payment_Amount__c,
                npe01__Payment_Date__c,
                npe01__Scheduled_Date__c,
                npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (existing.isEmpty()) {
            // NPSP did not auto-create a payment; create the single paid one.
            insert as user new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        // Keep the first payment NPSP created, remove any duplicates,
        // then correct the keeper to the full paid gift.
        npe01__OppPayment__c keeper = existing[0];
        List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existing.size(); i++) {
            duplicates.add(existing[i]);
        }
        if (!duplicates.isEmpty()) {
            delete as user duplicates;
        }

        if (
            keeper.npe01__Payment_Amount__c != amount ||
            keeper.npe01__Payment_Date__c != giftDate ||
            keeper.npe01__Scheduled_Date__c != giftDate ||
            keeper.npe01__Paid__c != true
        ) {
            keeper.npe01__Payment_Amount__c = amount;
            keeper.npe01__Payment_Date__c = giftDate;
            keeper.npe01__Scheduled_Date__c = giftDate;
            keeper.npe01__Paid__c = true;
            update as user keeper;
        }
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String donorName = '';
        if (!String.isBlank(donor.FirstName)) {
            donorName += donor.FirstName.trim();
        }
        if (!String.isBlank(donor.LastName)) {
            donorName = (String.isBlank(donorName) ? '' : donorName + ' ') +
                donor.LastName.trim();
        }
        return donorName + ' Donation ' + formatDate(giftDate);
    }

    private static String formatDate(Date d) {
        return String.valueOf(d.year()) +
            '-' + String.valueOf(d.month()).leftPad(2, '0') +
            '-' + String.valueOf(d.day()).leftPad(2, '0');
    }

    private static Id getDonationRecordTypeId() {
        Map<String, Schema.RecordTypeInfo> infosByDeveloperName =
            Opportunity.SObjectType.getDescribe().getRecordTypeInfosByDeveloperName();
        Schema.RecordTypeInfo donationInfo = infosByDeveloperName.get('Donation');
        if (donationInfo != null && donationInfo.isAvailable() && !donationInfo.isMaster()) {
            return donationInfo.getRecordTypeId();
        }
        return null;
    }
}
